import fs from 'node:fs/promises';
import {PGlite} from '@electric-sql/pglite';
export const org='10000000-0000-4000-8000-000000000001',other='10000000-0000-4000-8000-000000000002',owner='20000000-0000-4000-8000-000000000001',consultant='20000000-0000-4000-8000-000000000002',member='20000000-0000-4000-8000-000000000003',outsider='20000000-0000-4000-8000-000000000004';
export const rpc=async(d,name,args)=>(await d.query(`select to_jsonb(public.${name}(${args.map((_,i)=>'$'+(i+1)).join(',')})) as result`,args)).rows[0].result;
export const root=async(d,sql,args=[])=>{await d.exec('reset role');try{return await d.query(sql,args)}finally{await d.exec('set role service_role')}};
export async function fixture(){
 const d=new PGlite();await d.exec(`create schema private;create role anon;create role authenticated;create role service_role bypassrls;
 create table organizations(id uuid primary key);create table organization_members(organization_id uuid,user_id uuid,role text,primary key(organization_id,user_id));create table staff_accounts(user_id uuid,active boolean,role text);
 create table integrations(id uuid not null default gen_random_uuid() primary key,organization_id uuid not null,system_id uuid,name text not null,provider text,integration_type text not null default 'API'::text,status text not null default 'Planned'::text,authentication_method text,scopes text,data_classification text not null default 'Internal'::text,last_health_check_at timestamp with time zone,notes text,created_by uuid not null,created_at timestamp with time zone not null default now(),updated_at timestamp with time zone not null default now(),oauth_revision uuid not null default gen_random_uuid(),constraint integrations_data_classification_check CHECK ((data_classification = ANY (ARRAY['Public'::text, 'Internal'::text, 'Personal'::text, 'Sensitive'::text, 'Highly Sensitive'::text]))),constraint integrations_integration_type_check CHECK ((integration_type = ANY (ARRAY['API'::text, 'OAuth'::text, 'MCP'::text, 'Webhook'::text, 'Database'::text, 'File'::text, 'Other'::text]))),constraint integrations_status_check CHECK ((status = ANY (ARRAY['Planned'::text, 'Configuring'::text, 'Connected'::text, 'Degraded'::text, 'Blocked'::text, 'Disabled'::text]))));
 create table oauth_connections(id uuid not null default gen_random_uuid() primary key,organization_id uuid not null,integration_id uuid,provider text not null,tenant_id text,client_id text,scopes text[] not null default '{}'::text[],status text not null default 'Not Configured'::text,external_account_id text,external_account_name text,refresh_secret_id uuid,access_secret_id uuid,token_expires_at timestamp with time zone,last_connected_at timestamp with time zone,last_error text,created_by uuid not null,created_at timestamp with time zone not null default now(),updated_at timestamp with time zone not null default now(),client_secret_id uuid,oauth_verified_version integer not null default 0,oauth_revision uuid not null default gen_random_uuid(),oauth_refresh_revision uuid not null default gen_random_uuid(),constraint oauth_connections_organization_id_provider_key UNIQUE (organization_id, provider),constraint oauth_connections_provider_check CHECK ((provider = 'microsoft'::text)),constraint oauth_connections_status_check CHECK ((status = ANY (ARRAY['Not Configured'::text, 'Configured'::text, 'Consent Required'::text, 'Connected'::text, 'Expired'::text, 'Error'::text, 'Disabled'::text]))));
 create table private.fixture_vault(id uuid primary key default gen_random_uuid(),value text); -- synthetic-only replacement of existing encrypted production Vault wrappers
 create function public.edge_store_secret(text,text,text) returns uuid language plpgsql as $$declare v uuid;begin insert into private.fixture_vault(value) values($1) returning id into v;return v;end$$;
 create function public.edge_read_secret(uuid) returns text language sql as $$select value from private.fixture_vault where id=$1$$;
 create function public.edge_update_secret(uuid,text) returns void language plpgsql as $$begin update private.fixture_vault set value=$2 where id=$1;end$$;
 insert into organizations values('${org}'),('${other}');insert into organization_members values('${org}','${owner}','owner'),('${org}','${consultant}','consultant'),('${org}','${member}','member'),('${other}','${outsider}','owner');insert into staff_accounts values('${outsider}',true,'platform_admin');
 grant usage on schema private,public to service_role;grant all on all tables in schema public,private to service_role;revoke all on organization_members from service_role;grant select on organization_members to service_role;
 alter table oauth_connections enable row level security;alter table integrations enable row level security;`);
 for(const name of ['oauth-setup-contract.sql','oauth-refresh-contract.sql','company-email-oauth-contract.sql'])await d.exec(await fs.readFile(new URL('../../candidate/sql/'+name,import.meta.url),'utf8'));
 await d.exec('set role service_role');return d;
}
export async function begin(d,{provider='google',intent='read_send',actor=owner,organization=org,connection=null,revision=null}={}){
 const scopes=(await d.query('select private.email_requested_scopes($1,$2) s',[provider,intent])).rows[0].s;
 return rpc(d,'begin_company_email_oauth_setup',[organization,actor,provider,intent,connection,revision,provider==='google'?'google':'organizations',provider==='google'?'synthetic-client-123.apps.googleusercontent.com':owner,'SYNTHETIC-SECRET',scopes,'v'.repeat(64),'https://synthetic.example/functions/v1/'+provider+'-oauth-callback','a'.repeat(64)]);
}
export const claim=(d,s)=>rpc(d,'claim_company_email_oauth_setup',[s.state,s.provider]);
export const stage=(d,s,patch={})=>{const p={access:'SYNTHETIC-ACCESS',refresh:'SYNTHETIC-REFRESH',expires:new Date(Date.now()+3600000).toISOString(),id:'provider-stable-sub',name:'Synthetic User',email:'verified@example.test',scopes:s.scopes,...patch};return rpc(d,'stage_company_email_oauth_setup',[s.state,s.provider,p.access,p.refresh,p.expires,p.id,p.name,p.email,p.scopes,'b'.repeat(64)])};
export const finish=(d,s,{actor=owner,organization=org,browser='a'.repeat(64),completion='b'.repeat(64)}={})=>rpc(d,'finish_company_email_oauth_setup',[organization,actor,s.state,browser,completion]);
export const complete=async(d,s,patch={})=>{await stage(d,s,patch);await finish(d,s);return true};
export async function connected(d,options){const s=await begin(d,options);await claim(d,s);await complete(d,s);return (await d.query('select * from oauth_connections where id=$1',[s.connection_id])).rows[0]}
export const binding=async(d,c)=>(await d.query('select private.email_connection_binding(c,i) b from oauth_connections c join integrations i on i.id=c.integration_id where c.id=$1',[c.id])).rows[0].b;
